<script>
 import {studio,liveAssets,asset} from '../studio.svelte';import {selection} from '../stores/selection.svelte';import {chooseExportScope} from '../services/export.js';
 const context=$derived(selection.context||selection.snapshot());const labels={mention:'@引用',selected:'已选',editor:'当前图',filter:'筛选结果'};
 function choose(event){const value=event.currentTarget.value;if(value!=='auto')chooseExportScope(value);event.currentTarget.value='auto';}
</script>
<div class="scope-picker"><label>处理范围<select aria-label="处理范围" value="auto" onchange={choose} disabled={!!studio.busy}><option value="auto">{labels[context.resolvedTarget.source]}（{context.resolvedTarget.ids.length} 张）</option>{#if asset()}<option value="current">仅当前图片</option>{/if}<option value="selection">使用已勾选图片（{selection.selectedIds.length}）</option><option value="project">选择项目全部图片（{liveAssets().length}）</option></select></label><span>{context.resolvedTarget.ids.length} 张图片</span><div class="scope-thumbs">{#each context.resolvedTarget.ids.slice(0,4) as id}{#if studio.thumbs[id]}<img src={studio.thumbs[id]} alt=""/>{/if}{/each}{#if context.resolvedTarget.ids.length>4}<b>+{context.resolvedTarget.ids.length-4}</b>{/if}</div></div>
